// Canonical capability checks for the private dynamic profile. The embedded
// production copy is generated by scripts/update-runtime-profile.mjs.
export function installPrivateDynamicProfile(delegate = globalThis.fetch) {
  // Production installs a locked adapter before importing user code. A bundled
  // local-development bootstrap must preserve that broker-backed adapter.
  if (Object.getOwnPropertyDescriptor(globalThis, "fetch")?.configurable === false) return;
  const unavailableCache = () => {
    throw new TypeError("Cache API is unavailable in the private dynamic profile");
  };
  const nativeStorage = globalThis.caches;
  if (nativeStorage) {
    const nativeCache = nativeStorage.default;
    for (const [object, names] of [
      [Object.getPrototypeOf(nativeStorage), ["open"]],
      [Object.getPrototypeOf(nativeCache), ["match", "put", "delete"]],
    ]) {
      for (const name of names)
        Object.defineProperty(object, name, {
          value: unavailableCache,
          writable: false,
          configurable: false,
        });
    }
    Object.defineProperty(globalThis, "caches", { get: unavailableCache, configurable: false });
  }
  Object.defineProperty(globalThis, "fetch", {
    async value(input, init) {
      if (init?.cf) throw new TypeError("Custom fetch/cache options are unavailable");
      const request = new Request(input, init);
      // Request.cf may contain platform metadata on ingress. Only the explicit
      // fetch-init options are restricted; don't reject forwarded ingress.
      validatePrivateDynamicRequest(request);
      return delegate(request);
    },
    writable: false,
    configurable: false,
  });
}

export function validatePrivateDynamicRequest(request) {
  const url = new URL(request.url);
  if (url.username || url.password) throw new TypeError("URL credentials are unavailable");
  if (request.headers.has("upgrade")) throw new TypeError("Outbound WebSockets are unavailable");
}
